def find():
    import os,re,glob
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    base=d+'/'+'../../sessions'
    best=None
    for p in glob.glob(base+'/*.jsonl'):
        t=open(p).read().replace('\\n','\n')
        k=[m[1] for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \(\d+x\d+\):\n',t)]
        if 'Test input' not in k and any('output' in s for s in k):
            pass
        if 'Test input' not in k: continue
        # extract only grids from THIS conversation's own file where test at bottom
        G={}
        for m in re.finditer(r'(Demo pair (\d+) (input|output)|Test input) \((\d+)x(\d+)\):\n',t):
            tag,h,w=m[1],int(m[4]),int(m[5])
            rows=[r.split() for r in t[m.end():].split('\n')[:h]]
            if all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
                if tag=='Test input':
                    G['T']=[[int(x) for x in r] for r in rows]
                elif tag.startswith('Demo pair 7') or tag.startswith('Demo pair 8'):
                    n=m[2]
                    key='D'+n
                    G[key]=([[int(x) for x in r] for r in rows], None)
        if 'T' in G and len(G)>0:
            return G
    return None
