def solve(g):
    h,w=len(g),len(g[0])
    cnt=Counter(x for r in g for x in r)
    bg=max(cnt,key=lambda c:cnt[c])
    best=None; maxn=-1
    for dr,dc,name in [(1,-1,'dl')]:
        for p in range(2,h+1):
            fam={}
            ok=True
            for i in range(h):
                for j in range(w):
                    v=g[i][j]
                    if v==bg: continue
                    k=(i*dr+j*dc)%p
                    if k in fam and fam[k]!=v: ok=False;break
                    fam[k]=v
            if not ok: continue
            out=[[bg]*w for _ in range(h)]
            for i in range(h):
                for j in range(w):
                    out[i][j]=fam.get((i*dr+j*dc)%p,bg)
            nm=sum(1 for i in range(h) for j in range(w) if g[i][j]!=bg and out[i][j]==g[i][j])
            nbad=sum(1 for i in range(h) for j in range(w) if g[i][j]!=bg and out[i][j]!=g[i][j])
            if nbad==0 and (best is None or nm>maxn):
                maxn=nm; best=(name,p,out,nm)
    return best
